import { useEffect, useState } from 'react';

import { usePinnedState } from './store/selectors.js';
import { useOverlaysEvents } from '../../core/hooks/useOverlaysEvents.js';
import { MouseCoordinate } from '../../core/types/overlays.js';

export const useMousePosition = () => {
  const { mousePosition } = useOverlaysEvents();
  const { pinned } = usePinnedState();
  const [lastMousePosition, setLastMousePosition] = useState<
    MouseCoordinate | undefined
  >();

  useEffect(() => {
    if (!pinned) {
      setLastMousePosition(mousePosition);
    }
  }, [mousePosition, pinned]);

  return lastMousePosition;
};
